 public SurvivalScreen(Game game){super(game);for(int i=0;i<Data.N;i++)if(Data.nationalDex(i)==Save.profileAvatarDex&&Save.ownsDex(Save.profileAvatarDex)&&!Save.inCamp(i)){hero=i;break;}if(hero>=0)run=new SurvivalRun(hero,(int)System.currentTimeMillis());}
