 int py=y+25,avatarY=y+7;g.setClip(4,avatarY,32,32);PetAvatar.draw(g,run.sp,run.form,run.mega,run.shiny,4,avatarY,32);g.setClip(0,0,W,H);panelLine(g,Lang.t("Cấp: ","Lv: ")+run.level,4,avatarY+35,36,0xFFE080);
